window.__CONTENT__ = {"name":"Juan Pablo García","domain":"https://garciajp.com","description":"Juan Pablo García, AI developer in Argentina. RAG pipelines and multi-agent systems, built for production and measured with evals.","email":"jpgarcia2154@gmail.com","location":"San Juan, Argentina (UTC−3)","person":{"jobTitle":"AI Developer","locality":"San Juan","region":"San Juan","country":"AR","alumniOf":["University of Pennsylvania","Universidad de Palermo"],"worksFor":"Nodos Hub","knowsAbout":["Retrieval-augmented generation","Multi-agent systems","LLM evaluation","Python","FastAPI","React","PostgreSQL","Vector search"]},"calUser":"","analytics":{"goatcounter":"jpgarcia2154"},"writingOrder":["how-rlhf-works","how-dpo-works","how-to-evaluate-llm-apps","how-rag-works","how-ai-agents-work","how-mcp-works","how-lora-fine-tuning-works","how-transformers-work","how-vector-search-works","how-neural-networks-learn","how-diffusion-models-work","how-a-web-request-is-served","how-database-indexes-work","how-docker-containers-work"],"resumePdf":"resume.pdf?v=559e6efc","booked":["2026-10"],"links":{"github":"https://github.com/jpgg2105","linkedin":"https://www.linkedin.com/in/juan-pablo-garcia-guerrero","x":"https://x.com/garciajpgg21"},"projects":[{"slug":"research-agent","title":"Research agent with its own benchmark","client":"Personal project","role":"Author","when":"2026","summary":"A RAG service, a four-agent research loop and a benchmark that tests whether the loop beats a single LLM call.","problem":"Multi-agent systems are easy to demo. I wanted to know whether a multi-agent loop actually beats a single LLM call on the same questions.","solution":"Three parts that build on each other: ai-document-analyst, a RAG service with hybrid retrieval; research-agent, a four-role agent that uses it as a tool; and agent-benchmark, a harness that runs both approaches on the same questions.","flows":[{"title":"The agent loop","steps":[["Question",""],["Planner","Plans the research"],["Researcher","Calls the RAG service"],["Critic","Reviews the draft"],["Synthesizer","Writes the final answer"]]},{"title":"Inside the RAG service","steps":[["BM25","Keyword match"],["Dense vectors","Semantic match"],["Cross-encoder","Reranks the merged results"]]}],"notes":["The benchmark harness runs the agent loop and a single-shot baseline on the same questions.","CI and tests run without API keys, so anyone can reproduce the setup."],"stack":["Python","FastAPI","React","Docker","GitHub Actions","pytest"],"result":"A reproducible way to compare the agent loop with a single LLM call, instead of judging it by a demo.","code":"https://github.com/jpgg2105","codeNote":"","demo":"","tour":{"scene":"proj_research","steps":[["One question, two contenders","The project asks a simple question: on the same questions, does a four-agent loop give better answers than a single LLM call?"],["The RAG service finds the evidence","ai-document-analyst runs keyword search (BM25) and semantic search (dense vectors), merges the candidates and reranks them with a cross-encoder."],["Four roles work in a loop","A planner plans the research, a researcher gathers evidence through the RAG service, a critic reviews the draft and sends unsupported claims back, and a synthesizer writes the answer."],["The benchmark runs both","agent-benchmark sends the same questions to the agent loop and to a single-shot baseline, and scores every answer the same way."],["Anyone can rerun it","CI and tests run without API keys, so anyone can clone the project and reproduce the setup."]]}},{"slug":"schools-analytics-dashboard","hideOnHome":true,"title":"Analytics dashboard for hundreds of schools","client":"Nodos Hub","role":"AI developer","when":"2025 to now","summary":"A React and FastAPI dashboard in production, following attendance, performance and risk across hundreds of schools.","problem":"An education-sector client needed attendance, performance and risk indicators for hundreds of schools in one place, behind their own sign-in.","solution":"A FastAPI backend and a React dashboard with Excel export, signed in through the client's identity system. I own the whole path to production.","flows":[{"title":"How a request flows","steps":[["Sign-in","SSO with the client's identity system"],["API","FastAPI"],["Dashboard","React: attendance, performance, risk"],["Export","Excel"]]},{"title":"How it ships","steps":[["GitLab","Source and pipeline"],["Cloud Linux server","Gunicorn, systemd, nginx"],["Dev and prod","Separate environments"]]}],"notes":[],"stack":["React","FastAPI","Python","Linux","Gunicorn","systemd","nginx","SSO"],"result":"In production, used to follow students across hundreds of schools.","code":"","codeNote":"Client work, code is private.","demo":"","tour":{"scene":"proj_schools","steps":[["One sign-in","Staff sign in through the client's own identity system, with the same accounts they already use."],["Hundreds of schools, one API","A FastAPI backend serves the data for every school to the dashboard."],["Attendance, performance and risk","The React dashboard puts the three indicators in one place, so problems are visible early."],["Export to Excel","Any view can be exported to a spreadsheet for reports and meetings."],["From GitLab to production","A GitLab pipeline ships to a cloud Linux server: nginx in front, Gunicorn running FastAPI, systemd keeping it up, with separate dev and prod environments."]]}},{"slug":"chatbots-and-outreach","title":"Chatbots and an outreach pipeline","client":"Nodos Hub","role":"AI developer","when":"2025","summary":"LLM chatbots that answer from client content, and a pipeline that finds leads and contacts them on WhatsApp.","problem":"Clients wanted assistants that answer from their own content, and a sales team was finding and contacting leads by hand.","solution":"Chatbots built on Gemini and Pinecone, in PHP and Python depending on the client's stack, and an n8n workflow that scrapes leads, stores them in Airtable, drafts messages with the OpenAI API and sends them on WhatsApp.","flows":[{"title":"Chatbots","steps":[["Client content","Indexed in Pinecone"],["Chatbot","Gemini, PHP or Python"]]},{"title":"Outreach","steps":[["Lead scraping",""],["Airtable","Lead records"],["OpenAI API","Drafts each message"],["WhatsApp","Sent through n8n"]]}],"notes":[],"stack":["Gemini","Pinecone","PHP","Python","n8n","Airtable","OpenAI"],"result":"Answers come from the client's own documents, and lead outreach runs without manual copying.","code":"","codeNote":"Client work, code is private.","demo":"","tour":{"scene":"proj_bots","steps":[["Index the client's content","The client's documents are split into chunks and stored as vectors in Pinecone."],["Answer from that content","The chatbot finds the relevant chunks and Gemini answers from them, in PHP or Python depending on the client's stack."],["Collect leads automatically","An n8n workflow scrapes leads instead of a sales team finding them by hand."],["Store and draft","Leads go into Airtable, and the OpenAI API drafts a message for each one."],["Send on WhatsApp","n8n sends each message on WhatsApp and the table keeps track of who was contacted."]]}}],"offers":[{"name":"Add AI to your product","meeting":1,"text":"Assistants and search that answer from your own documents and data, with a way to measure whether the answers are good.","items":["Retrieval tuned on your content","Answers that cite their sources","An evaluation set, so quality is measured instead of guessed"]},{"name":"Build the whole product","meeting":1,"text":"For founders and teams who need one person to own the backend, the interface and the deploy.","items":["Database, API, auth and roles","React interface","Deploy, monitoring and handover"]},{"name":"Automate a workflow","meeting":0,"text":"Connect the tools you already use so repetitive work runs by itself.","items":["Lead capture and outreach","Reports and exports","n8n, APIs and LLM steps where they help"]}],"process":[["Intro call","15 minutes to understand the problem and see if I'm the right fit."],["Written plan","Scope, timeline and price in writing before any work starts."],["Weekly demos","You see working software every week."],["Handover","Deployed, documented and walked through with your team."]],"resume":{"title":"AI Developer · RAG, agents and LLM evaluation","summary":"AI developer who builds RAG pipelines and multi-agent systems and measures whether they actually work. I've built products end to end as the only developer and run a production dashboard for hundreds of schools. Studying AI Engineering at Universidad de Palermo, after a year as an exchange student at the University of Pennsylvania. Open to remote roles; based in Argentina (UTC−3), English C2.","jobs":[{"when":"Feb 2025 to now","role":"AI Developer","at":"Nodos Hub · Remote","points":["Built a React and FastAPI analytics dashboard, now in production, tracking attendance, performance and risk across hundreds of schools for an education-sector client, with Excel export.","Own the deployment pipeline from GitLab to a cloud Linux server (Gunicorn, systemd, nginx) across separate dev and prod environments, with SSO against the client's identity system.","Built LLM chatbots (Gemini, Pinecone) in PHP and Python, plus an automated lead-scraping and WhatsApp outreach pipeline using n8n, Airtable and the OpenAI API."]},{"when":"Sep 2025 to Jul 2026","role":"AI Developer","at":"Glow Talent · Remote","points":["Built a multi-tenant SaaS platform from scratch as the sole developer, from database design to deployment, using Python, Flask, PostgreSQL, SQLAlchemy and Alembic.","Built retrieval-augmented generation (ChromaDB, Gemini) and LLM-based evaluation features.","Implemented role-based access control with JWT authentication, and automated QA with headless-browser testing."]}],"projects":[{"when":"Personal","role":"ai-document-analyst · research-agent · agent-benchmark","at":"Python, FastAPI, React, Docker","points":["A RAG service with hybrid retrieval (BM25, dense vectors, cross-encoder reranking), a Planner, Researcher, Critic and Synthesizer multi-agent system that uses it as a tool, and a benchmark harness that compares the agent loop with a single-shot baseline. CI and tests run without API keys."]}],"education":[{"when":"2024 to 2029","role":"B.Eng. in Artificial Intelligence Engineering","at":"Universidad de Palermo · intermediate AI Analyst degree expected Dec 2026"},{"when":"2023 to 2024","role":"Full-year exchange, BSE Computer Science","at":"University of Pennsylvania · GPA 3.88/4.0, 80% scholarship, academic honors"},{"when":"2016 to 2022","role":"Electronics Technician","at":"Escuela Industrial D. F. Sarmiento · GPA 9.40, valedictorian (Abanderado)"}],"honors":["Bronze Medal, International Junior Science Olympiad (Qatar, 2019)","Gold Medal, National Junior Science Olympiad (2019)","80% scholarship, University of Pennsylvania; 100% scholarship offer, ITBA"],"languages":[["Spanish","native"],["English","C2"],["French","A2"],["Italian","basic"]]},"stack":[{"group":"AI and machine learning","items":["RAG","Gemini","OpenAI","Anthropic","ChromaDB","Pinecone","Qdrant","Multi-agent systems","PyTorch","scikit-learn"]},{"group":"Backend","items":["Python","FastAPI","Flask","REST APIs","SQLAlchemy","Alembic","JWT","RBAC","OAuth"]},{"group":"Frontend","items":["React","TypeScript","Vite","Tailwind CSS"]},{"group":"Infrastructure","items":["PostgreSQL","Docker","GitHub Actions","Git","Linux","Gunicorn","systemd","nginx","Azure","pytest","Playwright"]},{"group":"Languages","items":["Python","TypeScript","JavaScript","SQL","Java","PHP","C"]}],"shipped":["RAG","Gemini","OpenAI","ChromaDB","Pinecone","Python","FastAPI","Flask","SQLAlchemy","Alembic","JWT","RBAC","React","PostgreSQL","Linux","Gunicorn","systemd","nginx","PHP","SQL"],"meetings":[{"slug":"15min","name":"Intro call","mins":15,"desc":"See if we're a good fit"},{"slug":"30min","name":"Project scoping","mins":30,"desc":"Walk through your idea and timeline"},{"slug":"60min","name":"Technical consult","mins":60,"desc":"RAG, agents or architecture, in depth"}],"labels":{"explainer":"Explainers","article":"Articles","interview":"Interviews","note":"Notes"},"labelHelp":{"article":"Longer pieces on RAG, agents and shipping AI.","interview":"Conversations with builders and researchers.","note":"Short things I learned this week.","explainer":"Scroll-driven visual guides to how AI and software techniques work."},"posts":[{"slug":"how-rag-works","kind":"explainer","scene":"rag","ogFrame":5.9,"date":"2026-10-09","title":"How RAG works","excerpt":"Retrieval-augmented generation, step by step: from splitting documents to an answer with sources.","intro":"Retrieval-augmented generation lets a language model answer from your own documents instead of from memory. Scroll to follow a question from the documents to a cited answer.","steps":[["Split the documents","Long documents are cut into short chunks, a few paragraphs each, so the system can retrieve just the part that answers a question."],["Turn chunks into vectors","An embedding model turns each chunk into a list of numbers. Chunks with similar meaning land close together in this space."],["Embed the question","The question goes through the same embedding model, so it lands in the same space as the chunks."],["Find the nearest chunks","An approximate nearest-neighbor search returns the chunks closest to the question. It's fast, but closeness in embedding space is only a rough guess at relevance."],["Rerank","A reranker, usually a cross-encoder, reads the question and each candidate together and scores how well it actually answers. The order changes."],["Answer with sources","The top chunks go into the prompt. The model answers from them and cites the chunk behind each claim."]],"takeaways":["RAG keeps answers grounded in documents you control, and you can update them without retraining the model (Lewis et al., 2020).","Retrieval usually decides answer quality: chunking, the embedding model and reranking tend to matter more than prompt wording.","Hybrid search, keyword matching (BM25) plus vectors, catches exact terms like product codes that embeddings miss.","Evaluate retrieval and generation separately: was the right chunk retrieved, and did the answer stay faithful to it?"],"refs":[["Lewis et al. (2020). Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks. NeurIPS.","https://arxiv.org/abs/2005.11401"],["Robertson & Zaragoza (2009). The Probabilistic Relevance Framework: BM25 and Beyond. Foundations and Trends in IR.",null],["Nogueira & Cho (2019). Passage Re-ranking with BERT.","https://arxiv.org/abs/1901.04085"],["Karpukhin et al. (2020). Dense Passage Retrieval for Open-Domain Question Answering. EMNLP.","https://arxiv.org/abs/2004.04906"]]},{"slug":"how-ai-agents-work","kind":"explainer","scene":"agents","date":"2026-10-09","title":"How AI agents work","excerpt":"An agent is a language model in a loop: plan, call a tool, read the result, decide again.","intro":"An AI agent is a language model in a loop. It plans, calls tools, reads the results and decides what to do next until the goal is met or a limit is reached.","steps":[["Start from a goal","An agent gets a goal instead of a single question. A language model sits at the center and decides what to do next."],["Make a plan","Many agents first break the goal into steps they can act on. Others plan one step at a time, reasoning before each action."],["Call a tool","To act, the model writes a structured tool call, like a search with parameters. Your code runs the tool and returns the result."],["Observe and decide again","Each result goes back into the model's context. It picks the next action, and the loop continues."],["Stop when done","The loop ends when the goal is met or a limit is hit. Limits on steps, cost and permissions keep agents safe."]],"takeaways":["The model never runs anything itself. It proposes tool calls and your code executes them, which is where permissions belong.","Many failures come from unclear tools: names, descriptions and error messages matter as much as the prompt.","Cap the loop with a step and cost budget, and log every call so you can replay what happened.","For simple tasks a single call beats an agent. Use the loop when the next step depends on what the last one found.","Interleaving reasoning with tool calls is the ReAct pattern (Yao et al., 2022), the basis of most agent loops."],"refs":[["Yao et al. (2022). ReAct: Synergizing Reasoning and Acting in Language Models. ICLR 2023.","https://arxiv.org/abs/2210.03629"],["Schick et al. (2023). Toolformer: Language Models Can Teach Themselves to Use Tools. NeurIPS.","https://arxiv.org/abs/2302.04761"],["Anthropic (2024). Building effective agents.","https://www.anthropic.com/engineering/building-effective-agents"]]},{"slug":"how-transformers-work","kind":"explainer","scene":"transformer","date":"2026-10-09","title":"How transformers and attention work","excerpt":"What happens inside a large language model: tokens, embeddings, attention and next-token prediction.","intro":"Large language models are transformers. They split text into tokens, let every token look at the others through attention, and predict what comes next, one token at a time.","steps":[["Split text into tokens","The model reads tokens, pieces of words with an ID each, not letters or whole sentences."],["Give each token a vector","Each token ID is looked up in a table of learned vectors, its embedding. Word order enters through position information: today usually rotary embeddings, which rotate the queries and keys inside every attention layer."],["Attention: decide what to look at","For each token, attention scores the tokens before it by relevance and mixes in their information. In a GPT-style decoder a token can't look ahead. Here “it” looks mostly at “cat”."],["Many heads, many patterns","Attention runs in parallel heads, each learning a different pattern. Every layer pairs attention with a feed-forward network, and dozens of layers are stacked."],["Predict the next token","After many layers, the model gives a probability to every token in its vocabulary. One is picked, appended, and the process repeats."]],"takeaways":["Everything a model reads or writes is tokens, which is why context limits and prices are counted in tokens.","Attention compares each token with every earlier one, so its cost grows with the square of the context length.","Generation is repeated next-token prediction. Temperature rescales the probabilities: low values pick the likeliest token, higher values sample more varied ones.","The token IDs and percentages in the animation are illustrative."],"refs":[["Vaswani et al. (2017). Attention Is All You Need. NeurIPS.","https://arxiv.org/abs/1706.03762"],["Sennrich et al. (2016). Neural Machine Translation of Rare Words with Subword Units. ACL.","https://arxiv.org/abs/1508.07909"],["Su et al. (2021). RoFormer: Enhanced Transformer with Rotary Position Embedding.","https://arxiv.org/abs/2104.09864"],["Holtzman et al. (2020). The Curious Case of Neural Text Degeneration. ICLR.","https://arxiv.org/abs/1904.09751"]]},{"slug":"how-neural-networks-learn","kind":"explainer","scene":"neural","date":"2026-10-09","title":"How neural networks learn","excerpt":"Forward pass, loss, backpropagation and gradient descent, drawn one step at a time.","intro":"A neural network learns by guessing, measuring how wrong the guess was, and nudging its weights to be a little less wrong next time.","steps":[["Layers of neurons","A network is layers of simple units. Every connection has a weight, a number the network learns."],["Forward pass","Input values flow left to right. Each neuron adds up its weighted inputs plus a bias and applies a nonlinear activation such as ReLU."],["Measure the error","The output is compared with the right answer. A loss function turns the gap into a single number."],["Backpropagation","The error flows backward. Using the chain rule, backpropagation computes for every weight its gradient: how much the loss would change if that weight moved slightly."],["Gradient descent","Each weight moves a small step against its gradient, usually computed on a mini-batch of examples. Optimizers like Adam adapt the step size for each weight."]],"takeaways":["Training is a loop: forward pass, loss, backpropagation and update, repeated over many batches of examples.","The learning rate sets the step size. Too large and training diverges, too small and it crawls.","The same idea scales from this toy network to language models with billions of weights.","Without the nonlinear activations, any stack of layers would collapse into a single linear function."],"refs":[["Rumelhart, Hinton & Williams (1986). Learning representations by back-propagating errors. Nature 323.","https://doi.org/10.1038/323533a0"],["Goodfellow, Bengio & Courville (2016). Deep Learning. MIT Press.","https://www.deeplearningbook.org"],["Kingma & Ba (2015). Adam: A Method for Stochastic Optimization. ICLR.","https://arxiv.org/abs/1412.6980"]]},{"slug":"how-vector-search-works","kind":"explainer","scene":"vectors","date":"2026-10-09","title":"How embeddings and vector search work","excerpt":"How meaning becomes coordinates, and how a search finds the closest ones fast.","intro":"Embeddings turn meaning into numbers. Once text is a vector, finding related content becomes a question of distance.","steps":[["Meaning becomes coordinates","An embedding model maps words, sentences or images to vectors. Related things end up near each other."],["Close means similar","Similarity is usually the cosine of the angle between two vectors. A small angle means similar meaning. For normalized vectors, cosine, dot product and Euclidean distance rank results the same way."],["Search by meaning","Embed the query and return the closest vectors. “puppy” finds “dog” and “kitten” without sharing a letter."],["Search fast at scale","Comparing against millions of vectors one by one is slow. Approximate indexes like HNSW navigate a layered graph of neighbors and get close in a few hops."]],"takeaways":["Real embedding scores bunch up: unrelated text often scores 0.1 to 0.3 and close matches 0.6 to 0.9, and the scale differs by model, so a similarity threshold tuned for one model does not carry over. The scores in the animation come from a 2-D sketch.","Real embeddings have hundreds or thousands of dimensions. The 2D picture is a simplification.","Use the same embedding model for documents and queries, or the distances mean nothing.","Approximate indexes like HNSW trade a little accuracy for a lot of speed, and the balance is tunable."],"refs":[["Mikolov et al. (2013). Efficient Estimation of Word Representations in Vector Space.","https://arxiv.org/abs/1301.3781"],["Reimers & Gurevych (2019). Sentence-BERT: Sentence Embeddings using Siamese BERT-Networks. EMNLP.","https://arxiv.org/abs/1908.10084"],["Malkov & Yashunin (2016). Efficient and robust approximate nearest neighbor search using Hierarchical Navigable Small World graphs. IEEE TPAMI.","https://arxiv.org/abs/1603.09320"]]},{"slug":"how-a-web-request-is-served","kind":"explainer","scene":"web","date":"2026-10-09","title":"How a web request is served","excerpt":"Load balancing, caching and the database: the path most web requests take.","intro":"Most web systems follow the same path: a load balancer spreads requests across servers, a cache answers the common ones fast, and a database holds the truth.","steps":[["A request arrives","A browser sends a request. Before any of your code runs, it reaches a load balancer."],["Spread the load","The load balancer sends each request to a different server, so no single machine gets overwhelmed."],["Check the cache first","The server asks an in-memory cache for the answer. A hit comes back in a couple of milliseconds."],["Fall back to the database","On a miss, the server queries the database, which is slower, then stores the result in the cache for the next request. This is the cache-aside pattern."],["Scale out","When traffic grows, add servers behind the balancer. Watch the slowest requests (p99), not only the average."]],"takeaways":["A cache is the cheapest speedup. Keeping it from serving stale data is the hard part.","Stateless servers are easy to scale out. Keep sessions and data in shared stores.","Tail latency matters more than it seems: when one page waits on many backend calls, the slowest 1% shapes what most users feel (Dean & Barroso, 2013).","The latencies in the animation are illustrative. Measure your own percentiles."],"refs":[["Dean & Barroso (2013). The Tail at Scale. Communications of the ACM 56(2).","https://doi.org/10.1145/2408776.2408794"],["Nishtala et al. (2013). Scaling Memcache at Facebook. NSDI.","https://www.usenix.org/conference/nsdi13/technical-sessions/presentation/nishtala"],["Kleppmann (2017). Designing Data-Intensive Applications. O'Reilly.",null]]},{"slug":"how-lora-fine-tuning-works","kind":"explainer","scene":"lora","date":"2026-10-09","title":"How fine-tuning with LoRA works","excerpt":"Why LoRA trains a fraction of a percent of the weights and still adapts a model.","intro":"Fine-tuning adapts a pretrained model to your task. LoRA does it by freezing the original weights and training two small matrices beside them.","steps":[["Start from a pretrained model","A language model is mostly large weight matrices. This one, W, has 4096 × 4096 entries, about 16.8 million numbers, and it already knows language."],["Full fine-tuning changes everything","Classic fine-tuning updates every weight. The optimizer also keeps extra state per weight, so memory and cost grow with the whole model."],["Freeze W, add two thin matrices","LoRA leaves W untouched and adds B (4096 × 8) and A (8 × 4096). Their product has W's shape but only 65,536 trainable numbers. B starts at zero, so training begins exactly at the pretrained model."],["Train only A and B","Gradients flow to A and B alone. The change B·A can only express a few directions, its rank, which is usually enough for a new task."],["Merge or swap","Add B·A into W for zero extra cost when serving, or keep adapters separate and swap them per task on one base model."]],"takeaways":["LoRA trains well under 1% of the parameters, so gradients and optimizer state shrink and it fits on smaller GPUs. The frozen weights still have to fit; QLoRA stores them in 4 bits.","The rank (8 here) sets how much the adapter can change. Higher rank, more capacity and more memory.","QLoRA goes further by storing the frozen base in 4-bit, so even larger models fit on one GPU.","Try prompting and RAG first. Fine-tune when you need a consistent style, format or behavior that prompts can't hold.","It works because the weight change needed to adapt a large model appears to have low rank: Hu et al.'s hypothesis, motivated by the low intrinsic dimension Aghajanyan et al. (2021) measured."],"refs":[["Hu et al. (2021). LoRA: Low-Rank Adaptation of Large Language Models. ICLR 2022.","https://arxiv.org/abs/2106.09685"],["Dettmers et al. (2023). QLoRA: Efficient Finetuning of Quantized LLMs. NeurIPS.","https://arxiv.org/abs/2305.14314"],["Aghajanyan et al. (2021). Intrinsic Dimensionality Explains the Effectiveness of Language Model Fine-Tuning. ACL.","https://arxiv.org/abs/2012.13255"]]},{"slug":"how-diffusion-models-work","kind":"explainer","scene":"diffusion","ogFrame":4.9,"date":"2026-10-09","title":"How diffusion models generate images","excerpt":"Image generators learn to remove noise, then start from pure noise and clean it up step by step.","intro":"Image generators like Stable Diffusion learn one skill: removing a little noise from an image. Run that skill many times, starting from pure noise, and a new image appears.","steps":[["Add noise, step by step","Training defines a schedule that adds a little Gaussian noise per step over many steps (often 1,000) until nothing of the image is left; each example jumps straight to a random step in one closed-form shot."],["Learn to predict the noise","A neural network sees a noisy image and the step number, and predicts the noise that was added. The loss measures how far off the prediction is."],["Start from pure noise","To generate, start from an image of random noise and a prompt. There is no picture hidden in the noise yet."],["Remove noise a little at a time","At each step the network predicts the noise and removes some of it. With a modern sampler, a few dozen steps leave a clean image."],["Guide it with text","A text encoder turns the prompt into vectors the denoiser reads at every step. Classifier-free guidance runs it with and without the prompt and pushes toward the difference."]],"takeaways":["The model doesn't keep a library of images to copy, but it can memorize a small number of heavily duplicated training images (Carlini et al., 2023).","Most modern generators run the process in a compressed latent space, then decode to pixels at the end. That is far cheaper (Rombach et al., 2022).","Fewer denoising steps means faster images. Samplers like DDIM trade steps against quality.","The image and the noise in the animation are drawn by hand, not produced by a real model."],"refs":[["Ho, Jain & Abbeel (2020). Denoising Diffusion Probabilistic Models. NeurIPS.","https://arxiv.org/abs/2006.11239"],["Song, Meng & Ermon (2021). Denoising Diffusion Implicit Models. ICLR.","https://arxiv.org/abs/2010.02502"],["Rombach et al. (2022). High-Resolution Image Synthesis with Latent Diffusion Models. CVPR.","https://arxiv.org/abs/2112.10752"],["Ho & Salimans (2022). Classifier-Free Diffusion Guidance.","https://arxiv.org/abs/2207.12598"],["Carlini et al. (2023). Extracting Training Data from Diffusion Models. USENIX Security.","https://arxiv.org/abs/2301.13188"]]},{"slug":"how-mcp-works","kind":"explainer","scene":"mcp","ogFrame":1.9,"date":"2026-10-09","title":"How MCP connects AI apps to tools","excerpt":"The Model Context Protocol, step by step: discovery, tool calls, and why one server works in every app.","intro":"The Model Context Protocol (MCP) is an open standard for connecting AI applications to tools and data. Write a server once and any MCP app can use it.","steps":[["Without a standard","Every AI app needs its own integration with every tool. Three apps and four tools means twelve pieces of custom code."],["One protocol in the middle","With MCP, each app includes an MCP client and each tool sits behind an MCP server. Each side implements the protocol once."],["Discover what's available","The client asks the server which tools it offers, each with a name and an input schema. Since the 2026-07-28 revision every request is self-contained: it carries the protocol version and the client's capabilities, so there is no session to set up."],["Call a tool","The model picks a tool and the app, often after asking the user, sends a tools/call request. The server runs it and returns the result."],["Same server, any app","The GitHub server written once now works in a chat app, an IDE and an agent, with no extra integration work."]],"takeaways":["Servers can expose tools (actions), resources (data to read) and prompts (reusable templates).","Messages are JSON-RPC 2.0, sent over stdio for local servers or Streamable HTTP for remote ones.","The host app decides what the model may do. Asking before risky calls is the app's job.","Treat third-party servers like any dependency: tool descriptions and results can carry prompt injection."],"refs":[["Model Context Protocol specification.","https://modelcontextprotocol.io/specification"],["JSON-RPC 2.0 specification.","https://www.jsonrpc.org/specification"],["Anthropic (2024). Introducing the Model Context Protocol.","https://www.anthropic.com/news/model-context-protocol"]]},{"slug":"how-database-indexes-work","kind":"explainer","scene":"btree","date":"2026-10-09","title":"How database indexes work","excerpt":"Why an index turns a full table scan into a few reads, and what it costs on every write.","intro":"A database index is a sorted structure, usually a B+tree, the B-tree variant most databases use, that lets a query jump to matching rows instead of reading the whole table.","steps":[["Without an index, read everything","To find one email in an unsorted table, the database has to check every row. That's fine for 12 rows and slow for millions."],["An index is a sorted tree","The index keeps the emails sorted in a tree. The root holds separator keys, and the leaves hold every key with a pointer to its row."],["Search by following branches","To find kai, compare with the root's keys and go down the one branch that can contain it. A few reads replace a full scan."],["Ranges are cheap too","In a B+tree the leaves are linked in order, so a range like kai to ned walks from leaf to leaf without going back to the root."],["Writes pay the cost","Every insert must also go into each index. When a leaf is full it splits and the parent gains a key. More indexes, slower writes."]],"takeaways":["Index the columns you filter, join and sort on, and check the query plan (EXPLAIN) to confirm the index is used.","Real B-tree nodes hold hundreds of keys, so a million rows needs only about 3 or 4 levels.","A composite index on (a, b) helps queries on a, or on a and b together, but usually not on b alone (a few engines can skip-scan the first column, at a cost)."],"refs":[["Bayer & McCreight (1972). Organization and Maintenance of Large Ordered Indexes. Acta Informatica 1.","https://doi.org/10.1007/BF00288683"],["Comer (1979). The Ubiquitous B-Tree. ACM Computing Surveys 11(2).","https://doi.org/10.1145/356770.356776"],["PostgreSQL documentation: Indexes.","https://www.postgresql.org/docs/current/indexes.html"],["Winand. Use The Index, Luke.","https://use-the-index-luke.com"]]},{"slug":"how-docker-containers-work","kind":"explainer","scene":"docker","date":"2026-10-09","title":"How Docker containers work","excerpt":"Dockerfile, layers, caching, containers and registries: how one image runs the same everywhere.","intro":"Docker packages an app with everything it needs into an image, then runs that image as isolated containers on any machine with Docker.","steps":[["Write a Dockerfile","A Dockerfile lists the steps to build your app's environment: a base image, files to copy and commands to run."],["Build an image in layers","Each step that changes files becomes a read-only layer stacked on the one below. The image is that stack."],["Layers are cached","When you change your code, the first changed step and every step after it are rebuilt; the layers before it come from the cache. Put steps that rarely change first."],["Run containers","A container is a running instance of an image with its own writable layer. Several share one host kernel, isolated by Linux namespaces and limited by cgroups."],["Ship the same image anywhere","Push the image to a registry and pull it on a laptop, in CI or on a server. It runs the same way in all of them, as long as the image is built for that CPU architecture (amd64 or arm64)."]],"takeaways":["Containers share the host's kernel, so they start in well under a second and use far less memory than virtual machines.","Copy dependency files and install them before copying your code, so code changes don't reinstall everything.","Keep images small: slim base images and multi-stage builds cut size and attack surface.","On macOS and Windows, Docker Desktop runs containers inside a lightweight Linux virtual machine.","The layer sizes in the animation are illustrative."],"refs":[["Docker documentation: Build cache.","https://docs.docker.com/build/cache/"],["Docker documentation: Multi-stage builds.","https://docs.docker.com/build/building/multi-stage/"],["Linux manual: namespaces(7).","https://man7.org/linux/man-pages/man7/namespaces.7.html"],["Linux manual: cgroups(7).","https://man7.org/linux/man-pages/man7/cgroups.7.html"]]},{"slug":"how-to-evaluate-llm-apps","kind":"explainer","scene":"evals","date":"2026-10-09","title":"How to evaluate an LLM app","excerpt":"Test cases, scoring, version comparisons and a release gate: measuring quality instead of guessing.","intro":"LLM apps fail in quiet ways. An evaluation set turns 'it seems better' into a number you can compare between versions and check before every release.","steps":[["Collect real test cases","Start with questions real users ask, each with the answer or behavior you expect. A few dozen real, well-labeled cases are a better start than thousands of synthetic ones."],["Run the app on every case","Run your full app, prompt, retrieval and model, on each case, exactly as users would hit it."],["Score each answer","Use exact checks where you can, and an LLM judge with a clear rubric where you can't. Judges favor one position, longer answers and their own outputs, so check them against human labels."],["Compare versions","Run the same cases on every change. Now a new prompt or model is a measured difference, not a feeling."],["Gate releases","Set minimums and run evals in CI. A version that drops below them by more than the noise, or breaks cases that used to pass, is blocked before it reaches users."]],"takeaways":["Look at failures, not just averages: each failed case usually points to a specific fix.","Track quality, cost and latency together. A better answer that takes three times longer may not be better.","Keep adding cases from real failures in production, so the set keeps up with how people use the app.","Small eval sets are noisy. Report confidence intervals before calling a two-point difference real (Miller, 2024).","The cases and scores in the animation are illustrative."],"refs":[["Zheng et al. (2023). Judging LLM-as-a-Judge with MT-Bench and Chatbot Arena. NeurIPS.","https://arxiv.org/abs/2306.05685"],["Miller (2024). Adding Error Bars to Evals: A Statistical Approach to Language Model Evaluations.","https://arxiv.org/abs/2411.00640"],["Liang et al. (2022). Holistic Evaluation of Language Models (HELM).","https://arxiv.org/abs/2211.09110"],["Husain (2024). Your AI Product Needs Evals.","https://hamel.dev/blog/posts/evals/"]]},{"slug":"how-to-break-down-a-problem","notes":true,"kind":"explainer","scene":"decompose","date":"2026-10-12","title":"How to break down a big problem","excerpt":"Split a vague problem into parts that add up to the whole, until each part is small enough to check and fix.","intro":"Most problems feel hard because they're vague. Splitting one into parts that don't overlap and add back up to the whole turns 'sales are down' into one specific question you can answer.","steps":[["Write the problem as one sentence","Turn the worry into a statement you can measure: what changed, by how much, since when. A clear sentence already rules out half the guesses."],["Split it into parts that make up the whole","Pick a split where the parts add or multiply back to the problem and don't overlap. Revenue is customers times what each one spends."],["Keep splitting until each part is measurable","Go one level deeper wherever a part is still too broad to check. Stop when each part is something you can look up or test."],["Check each part with numbers","Put a number on every part. Most turn out fine, and the one that explains the change stands out."],["Work on the part that moved","Follow the path down to that part and ask a specific question about it. Small, clear questions get answered; big, vague ones don't."]],"takeaways":["A good split is MECE, mutually exclusive and collectively exhaustive: nothing falls through the gaps and nothing is counted twice (Minto, 1987).","If one split doesn't help, try another: by step, by type of customer, by place, by time.","In the example, new and returning customers were 40% and 60% of the old total, so −3% and −31% combine to −20%. Always check that the parts add back up.","It works the same for a bug, a budget, a slow process or a personal goal. The numbers in the animation are illustrative."],"refs":[["Minto (1987). The Pyramid Principle: Logic in Writing and Thinking. Pearson.",null],["Pólya (1945). How to Solve It. Princeton University Press.",null]]},{"slug":"how-to-find-the-root-cause","notes":true,"kind":"explainer","scene":"whys","date":"2026-10-12","title":"How to find the root cause of a problem","excerpt":"Ask why, answer with facts, and keep going until you reach a cause you can change, so the problem doesn't come back.","intro":"Fixing what you can see makes the problem go away today and come back next week. Asking 'why' a few times in a row, a method from the Toyota Production System, walks you from the symptom down to the cause that keeps producing it.","steps":[["Start from what went wrong","Describe the problem as it happened, without blame or guesses: what, when, how often."],["Ask why, and answer with a fact","Each answer should be something you checked, not something that sounds likely. A guess sends you down the wrong branch."],["Keep asking why","Each answer becomes the next question. It often takes about five rounds, sometimes fewer, sometimes more."],["Stop at a cause you can change","You're done when the answer is a process, a rule or a missing check you control, not a person or bad luck."],["Fix the cause, not the symptom","Rushing one late delivery helps once. Changing how the work is ordered stops the next ones."]],"takeaways":["If an answer is 'someone made a mistake', ask why the process let that mistake through.","Five whys follows one chain and can stop at the first plausible answer. For complex failures, pair it with a fishbone (Ishikawa) diagram or a fault tree (Card, 2017).","It works for outages, missed deadlines, recurring arguments and failed projects.","The example in the animation is illustrative."],"refs":[["Ohno (1988). Toyota Production System: Beyond Large-Scale Production. Productivity Press.",null],["Card (2017). The problem with '5 whys'. BMJ Quality & Safety 26(8).","https://doi.org/10.1136/bmjqs-2016-005849"],["Ishikawa (1986). Guide to Quality Control. Asian Productivity Organization.",null]]},{"slug":"how-to-find-what-broke-by-halving","notes":true,"kind":"explainer","scene":"bisect","date":"2026-10-12","title":"How to find what broke by halving","excerpt":"When something worked before and doesn't now, test the middle and throw away half the suspects each time.","intro":"Something worked last month and doesn't now, and sixteen things changed in between. Checking them one by one can take sixteen tries. Testing the middle and discarding half each time takes four.","steps":[["Find one good state and one bad one","You need a point where it worked and a point where it doesn't. Everything that changed in between is a suspect."],["Test the middle","Go back to the state halfway between and check it. If it works, the cause is in the second half."],["Throw away the half that's fine","Each test cuts the suspects in half, whichever way it comes out. Both results are useful."],["Repeat until one is left","Keep testing the middle of what's left. Sixteen suspects take four tests."],["Count the tests","Halving grows slowly: a thousand suspects take about ten tests, a million about twenty."]],"takeaways":["It needs a quick, reliable test that says works or doesn't. Build that test first.","It assumes the problem appears at one change and stays. If it comes and goes across the history, halving can point to the wrong change.","If the problem only shows up sometimes, run each test more than once before you trust it.","It works on code history (git bisect), recipe changes, settings and wiring. The changes in the animation are illustrative."],"refs":[["Git documentation: git-bisect.","https://git-scm.com/docs/git-bisect"],["Knuth (1998). The Art of Computer Programming, Vol. 3: Sorting and Searching, §6.2.1 (binary search). Addison-Wesley.",null],["Zeller (2009). Why Programs Fail: A Guide to Systematic Debugging. Morgan Kaufmann.",null]]},{"slug":"how-to-find-the-bottleneck","notes":true,"kind":"explainer","scene":"bottleneck","date":"2026-10-12","title":"How to find the bottleneck","excerpt":"A process runs only as fast as its slowest step. Find that step, improve it, then look for the next one.","intro":"Any process, from a kitchen to a hiring pipeline to a factory, finishes work at the speed of its slowest step. Improving any other step looks productive and changes nothing. This is the core of the Theory of Constraints.","steps":[["Map the steps work goes through","Write down each step and how much it can handle in an hour, a day or a week."],["Look for where work piles up","Work waits in front of the slowest step. The pile is the easiest way to find it."],["Improving other steps changes nothing","Here, packing gets much faster and the output stays exactly the same."],["Widen the bottleneck","Add capacity where the work waits. Output rises until another step becomes the limit."],["Find the next one","Once one bottleneck is fixed, another step becomes the slowest. Check again after every change."]],"takeaways":["Goldratt's five focusing steps: identify the constraint, exploit it, subordinate everything else to it, elevate it, and repeat.","Before adding capacity, make sure the bottleneck never sits idle waiting for work or redoing work that gets thrown away.","A queue grows whenever work arrives faster than the bottleneck finishes it. By Little's law, work in progress = arrival rate × time in the system.","It works for teams, factories, support queues and sales funnels. The numbers in the animation are illustrative."],"refs":[["Goldratt & Cox (1984). The Goal: A Process of Ongoing Improvement. North River Press.",null],["Little (1961). A Proof for the Queuing Formula L = λW. Operations Research 9(3).","https://doi.org/10.1287/opre.9.3.383"],["Hopp & Spearman (2008). Factory Physics, 3rd ed. Waveland Press.",null]]},{"slug":"how-to-decide-what-to-fix-first","notes":true,"kind":"explainer","scene":"pareto","date":"2026-10-12","title":"How to decide what to fix first","excerpt":"Count the problems, sort them, and you usually find a few causes behind most of the trouble.","intro":"When everything seems urgent, counting beats arguing. Sort the causes by how often they happen and a few of them usually explain most of the problem. Joseph Juran named this the Pareto principle, after Vilfredo Pareto's observation that about 80% of Italy's land belonged to 20% of its people.","steps":[["Count the problems","Tally what's actually happening, from tickets, logs, returns or a notebook, instead of going by what feels worst."],["Sort from biggest to smallest","Put the most frequent cause first. The shape of the chart already tells you a lot."],["Add up the running total","The line shows how much of the problem the first causes explain together."],["Fix the few at the top","Here, three of seven causes account for 80% of complaints. That's where effort pays off most."],["Count again after fixing","Once the top cause shrinks, the order changes. Recount and pick the next one."]],"takeaways":["80/20 is a pattern, not a law. The split might be 70/30 or 90/10, but it's rarely even.","Weigh causes by cost when their impact differs: ten small annoyances can matter less than one lost customer.","It works for bugs, expenses, customer complaints, time spent and study topics.","The numbers in the animation are illustrative."],"refs":[["Juran (1951). Quality Control Handbook. McGraw-Hill.",null],["Pareto (1896). Cours d'économie politique. Lausanne: F. Rouge.",null]]},{"slug":"how-to-solve-problems-with-small-experiments","notes":true,"kind":"explainer","scene":"experiments","date":"2026-10-12","title":"How to solve problems with small experiments","excerpt":"Guess, test small, measure and adjust. Many cheap loops find a good answer faster than one big plan.","intro":"When you can't know the answer ahead of time, don't plan harder. Make a guess, test it as cheaply as you can, and let each result decide the next test.","steps":[["Turn the idea into a guess","Write down what you expect and how you'll measure it. 'Shorter pages get more signups' is testable; 'improve the page' isn't."],["Test it small and fast","Use the smallest test that gives a real result: a day, a sample, a prototype. Cheap tests let you run many."],["Change one thing and compare","While exploring, vary one thing at a time, so you know what made the difference."],["Repeat with smaller steps","When a result gets worse, you went too far. Step back and narrow in."],["Let the results find the answer","Five cheap tests found the best setting without ever seeing the full curve."]],"takeaways":["Decide what counts as success before you run the test, so the result can't be argued afterwards.","Stepping uphill finds a peak, not necessarily the highest one. Try a few distant starting points before settling.","When settings interact, changing one at a time misses it. A factorial design tests combinations with fewer runs (Box, Hunter & Hunter, 2005).","For tests on real users, fix the sample size in advance and don't stop the moment results look good (Kohavi et al., 2020). The curve in the animation is illustrative."],"refs":[["Box, Hunter & Hunter (2005). Statistics for Experimenters, 2nd ed. Wiley.",null],["Kohavi, Tang & Xu (2020). Trustworthy Online Controlled Experiments. Cambridge University Press.",null],["Deming (1986). Out of the Crisis. MIT Press.",null]]},{"slug":"how-ai-is-changing-software-development","notes":true,"kind":"explainer","scene":"aidev","date":"2026-10-12","title":"How AI is changing software development","excerpt":"From autocomplete to agents that ship whole features: specs, conducting, context and loops, how models run, and keeping agents safe.","intro":"AI isn't replacing developers, but it is changing what the job looks like. This explainer walks through the main ideas from a video on where software development is heading, from handing whole features to agents to keeping those agents safe.","steps":[["From autocomplete to whole features","AI used to suggest the next line, and fixing its output often took longer than writing the code yourself. Now coding agents take a whole feature: they read the codebase, write the code, run the tests and open a pull request for review."],["Write a spec, not a chat","Different models read the same prompt differently, and arguing with an agent wastes time. A written spec with the goal, the requirements and what counts as done gives the agent something clear to build and check against."],["From implementing to conducting","For decades the bottleneck was how fast and how well you could write code. Now the valuable part is deciding what to build: setting goals, making architecture decisions that matter a year from now, and splitting work into milestones agents can finish."],["Engineer the context and the loop","A model only sees what fits in its context window, so you choose what goes in: relevant code, tools, skills and data from MCP servers. Then, instead of prompting back and forth, you design a loop: you set the goal and when it's done, and the agent iterates until it gets there."],["Know how the model runs","The model's weights sit in GPU memory, and every token of the conversation adds to a KV cache next to them until memory runs out. Models also have no real sense of time: one may estimate weeks for a game it can prototype in minutes."],["Keep agents in a sandbox","An agent with access to private data, untrusted content and a way to send data out can be tricked by hidden instructions, for example in a pull request. Running it in a disposable sandbox with no secrets inside limits what a hijacked agent can do."]],"takeaways":["Skills, automations and sub-agents extend the same idea: reusable instructions, work triggered by events, and helpers that investigate a problem and report back.","The video quotes Andrew Ng's line that AI is the new electricity: like the power grid, it will need engineers who keep it reliable, safe and available.","Developers who are strong at architecture and critical thinking gain the most as coding agents improve.","The three-part risk in step 6 is what Simon Willison calls the lethal trifecta for AI agents.","The memory figures match an 8-billion-parameter model like Llama 3.1 8B at 16-bit precision. The other examples in the animation are illustrative."],"source":{"text":"Based on a video on YouTube about how AI is changing software development.","link":"Watch it on YouTube","url":"https://www.youtube.com/watch?v=hTAWHgQI4xg"},"refs":[["Willison (2025). The lethal trifecta for AI agents.","https://simonwillison.net/2025/Jun/16/the-lethal-trifecta/"],["Stanford GSB. Andrew Ng: Why AI Is the New Electricity.","https://www.gsb.stanford.edu/insights/andrew-ng-why-ai-new-electricity"],["Kwon et al. (2023). Efficient Memory Management for LLM Serving with PagedAttention. SOSP.","https://arxiv.org/abs/2309.06180"]]},{"slug":"how-rlhf-works","kind":"explainer","scene":"rlhf","ogFrame":2.6,"date":"2026-10-27","title":"How RLHF works","excerpt":"Reinforcement learning from human feedback, stage by stage: demonstrations, comparisons, a reward model, PPO with a KL leash, and reward hacking.","intro":"A pretrained language model predicts text; it doesn't follow instructions or know which answers people prefer. Reinforcement learning from human feedback (RLHF) closes that gap in three stages, and it is how InstructGPT and the first ChatGPT models were aligned.","steps":[["Start with supervised fine-tuning","Fine-tuning the pretrained model on human-written demonstrations, a prompt and an ideal answer, teaches it to follow instructions. This SFT model is the starting point and, later, the reference."],["Collect human comparisons","For each prompt the model writes several answers and a labeler ranks them. Comparing two answers is easier and more consistent than scoring one on an absolute scale."],["Train a reward model","A model initialized from the SFT checkpoint, often smaller than the policy, gets a scalar output and learns to score preferred answers higher. The Bradley–Terry model turns the score gap into a probability, P(A ≻ B) = σ(r(A) − r(B)), and training minimizes −log of it."],["Optimize with PPO on a KL leash","The policy generates answers, the frozen reward model scores them and PPO updates the policy. A KL penalty against the frozen SFT model keeps it near text the reward model can judge. PPO also trains a value model, so four models share the GPUs."],["Stop before reward hacking","The reward model is only a proxy. Optimize it too hard and the policy finds its blind spots: the score keeps rising while real quality falls (Gao et al., 2023). Teams tune β, stop early and refresh the reward model with new comparisons."]],"takeaways":["Labelers preferred the 1.3B-parameter InstructGPT over the 175B GPT-3, a model more than 100 times larger (Ouyang et al., 2022).","RLHF is cheap next to pretraining: InstructGPT's 175B PPO model took about 60 petaflop/s-days, against about 3,640 for GPT-3. The expensive part is good human labels.","RLAIF replaces some human labels with a model's judgments guided by written principles, as in Constitutional AI (Bai et al., 2022).","The reward scores and curves in the animation are illustrative; the Bradley–Terry arithmetic is exact."],"refs":[["Christiano et al. (2017). Deep Reinforcement Learning from Human Preferences. NeurIPS.","https://arxiv.org/abs/1706.03741"],["Stiennon et al. (2020). Learning to Summarize from Human Feedback. NeurIPS.","https://arxiv.org/abs/2009.01325"],["Ouyang et al. (2022). Training Language Models to Follow Instructions with Human Feedback. NeurIPS.","https://arxiv.org/abs/2203.02155"],["Schulman et al. (2017). Proximal Policy Optimization Algorithms.","https://arxiv.org/abs/1707.06347"],["Bradley & Terry (1952). Rank Analysis of Incomplete Block Designs: I. The Method of Paired Comparisons. Biometrika 39.","https://doi.org/10.2307/2334029"],["Gao, Schulman & Hilton (2023). Scaling Laws for Reward Model Overoptimization. ICML.","https://arxiv.org/abs/2210.10760"],["Bai et al. (2022). Constitutional AI: Harmlessness from AI Feedback.","https://arxiv.org/abs/2212.08073"]]},{"slug":"how-dpo-works","kind":"explainer","scene":"dpo","ogFrame":2.6,"date":"2026-10-27","title":"How DPO works, and when to use it instead of RLHF","excerpt":"Direct Preference Optimization turns RLHF's reward model and RL loop into one loss on preference pairs. The math, the trade-offs and when to choose it.","intro":"Direct Preference Optimization (DPO) aligns a model on the same preference pairs as RLHF, but without a separate reward model or a reinforcement learning loop. One derivation makes this possible, and it comes with trade-offs worth knowing before you pick a method.","steps":[["One loss instead of two stages","RLHF trains a reward model, then runs PPO with four models in memory. DPO (Rafailov et al., 2023) targets the same optimum with a single classification-style loss, using only the policy and a frozen reference."],["The policy is secretly a reward model","The KL-regularized RLHF objective has a closed-form optimum. Solving it for the reward gives r = β·log(π/π_ref) + β·log Z(x), and Z(x) cancels when two answers to the same prompt are compared."],["The DPO loss","Put that implicit reward into the Bradley–Terry model and you get one loss: raise the chosen answer's log-probability ratio relative to the rejected one's. It starts at log 2 ≈ 0.69 and falls as the margin grows."],["β and the offline catch","β sets how hard the reference pulls back; smaller β lets the model move further. Because DPO trains on a fixed dataset, the model can drift into regions its preference pairs never covered."],["Choosing between them","Use DPO for a simple, stable pipeline on existing pairs. Use RLHF or online RL when you need fresh samples, a reusable reward model or verifiable rewards. DPO-family variants such as IPO, KTO, ORPO and SimPO change the loss or the data. GRPO, behind recent reasoning models, is online RL without a value model, usually on verifiable rewards."]],"takeaways":["No method wins everywhere. Rafailov et al. found DPO matched or beat PPO on sentiment control, summarization and dialogue; Xu et al. (2024) found well-tuned PPO ahead on harder tasks such as code generation.","During DPO training the chosen answers' log-probabilities often fall too; the margin grows because the rejected ones fall faster (Pal et al., 2024).","Online or iterative DPO samples new answers from the current model and labels them each round, recovering part of RLHF's advantage.","For both methods, the consistency and expertise behind the preference labels set the ceiling, not the optimizer.","The log-ratios in the animation are illustrative. β = 0.5 is used for visibility; TRL's default is 0.1."],"refs":[["Rafailov et al. (2023). Direct Preference Optimization: Your Language Model is Secretly a Reward Model. NeurIPS.","https://arxiv.org/abs/2305.18290"],["Xu et al. (2024). Is DPO Superior to PPO for LLM Alignment? A Comprehensive Study. ICML.","https://arxiv.org/abs/2404.10719"],["Azar et al. (2023). A General Theoretical Paradigm to Understand Learning from Human Preferences (IPO). AISTATS 2024.","https://arxiv.org/abs/2310.12036"],["Ethayarajh et al. (2024). KTO: Model Alignment as Prospect Theoretic Optimization. ICML.","https://arxiv.org/abs/2402.01306"],["Hong, Lee & Thorne (2024). ORPO: Monolithic Preference Optimization without Reference Model. EMNLP.","https://arxiv.org/abs/2403.07691"],["Meng, Xia & Chen (2024). SimPO: Simple Preference Optimization with a Reference-Free Reward. NeurIPS.","https://arxiv.org/abs/2405.14734"],["Shao et al. (2024). DeepSeekMath: Pushing the Limits of Mathematical Reasoning in Open Language Models (GRPO).","https://arxiv.org/abs/2402.03300"],["Pal et al. (2024). Smaug: Fixing Failure Modes of Preference Optimisation with DPO-Positive.","https://arxiv.org/abs/2402.13228"],["Hugging Face TRL documentation: DPO Trainer.","https://huggingface.co/docs/trl/dpo_trainer"]],"source":{"text":"Prompted by Mercor's article","link":"DPO vs. RLHF: Comparison and when to use each","url":"https://www.mercor.com/resources/experts/dpo-vs-rlhf/"}}],"servicesTour":[["Add AI to your product","Assistants and search that answer from your own documents, cite their sources, and are checked against an evaluation set."],["Build the whole product","One person owns the database, API, auth, interface and deploy, and hands it over documented."],["Automate a workflow","Connect the tools you already use so repetitive work runs on its own, with LLM steps where they help."],["How a project runs","A 15-minute intro call, a written plan with scope and price, working demos every week, and a documented handover."]],"featured":["how-to-evaluate-llm-apps","how-rag-works","how-ai-agents-work"]};
